<script setup lang="ts">
import { useWorkspaceReveal } from '../utils/useWorkspaceReveal'
import {computed,onUnmounted,reactive,ref,shallowRef,watch} from 'vue'
import {onBeforeRouteLeave} from 'vue-router'
import { ElMessageBox } from 'element-plus'
import { feedback as ElMessage } from '../utils/feedback'
import {api,ApiError} from '../api/client'
import {can,contextGeneration,session,switchingTenant} from '../stores/session'
import {contextTransitionGuards} from '../utils/contextTransitionGuard'
import {createBackupPlanWorkspace,emptyBackupPlanState,type BackupPlanState} from '../utils/backupPlanWorkspace'
import {backupPlanUuid,type BackupPlanContext,type BackupPlanDetail} from '../utils/backupPlanDrafts'
import {validInspectionText} from '../utils/inspectionTemplates'
import {worksheetAssetChoices,type WorksheetAssetChoices} from '../utils/inspectionWorksheetForm'
import {displayTime} from '../utils/display'
import ApiErrorNotice from '../components/ApiErrorNotice.vue'
import BackupPlanFacts from '../components/BackupPlanFacts.vue'
const actions={CREATE:'新建',UPDATE:'修订',ARCHIVE:'归档',RESTORE:'恢复'}
const mode=ref<'CREATE'|'UPDATE'|null>(null),baseline=shallowRef<BackupPlanDetail|null>(null),initial=ref(''),validation=ref(''),expandedVersion=ref<number|null>(null),lookupId=ref('')
const form=reactive({name:'',dailyLocalTime:'02:00',credentialRef:'',intent:'',note:null as string|null})
const targets=ref<{id:string;name:string|null}[]>([]),targetPage=ref(0),targetRows=computed(()=>targets.value.slice(targetPage.value*10,targetPage.value*10+10))
const assetQuery=ref(''),assetApplied=ref(''),assets=shallowRef<WorksheetAssetChoices|null>(null),checkedAssets=ref<string[]>([]),assetError=shallowRef<unknown>(null),assetBusy=ref(false)
let assetEpoch=0,assetAbort:AbortController|null=null,disposed=false
const state=shallowRef<BackupPlanState>(emptyBackupPlanState()),workspace=createBackupPlanWorkspace(api,s=>{state.value=s})
const permitted=computed(()=>Boolean(session.value?.mode==='remote_test'&&session.value.user.role==='padmin'&&can('backup_plan_drafts:read')&&!switchingTenant.value))
const writable=computed(()=>permitted.value&&can('backup_plan_drafts:write')),canChooseAssets=computed(()=>writable.value&&can('assets:read'))
const locked=computed(()=>!writable.value||Boolean(state.value.busy)||Boolean(state.value.attempt)||assetBusy.value)
const contextKey=computed(()=>JSON.stringify([contextGeneration.value,session.value?.tenant.id,session.value?.user.id,session.value?.permission_version,session.value?.user.role,permitted.value,writable.value,canChooseAssets.value]))
function context():BackupPlanContext|null{const s=session.value;return s&&permitted.value?{tenantId:s.tenant.id,actorId:s.user.id,permissionVersion:s.permission_version,role:s.user.role,canRead:true,canWrite:writable.value}:null}
function payload(){return{expected_version:baseline.value?.version??0,name:form.name,target_asset_ids:targets.value.map(t=>t.id),daily_local_time:form.dailyLocalTime,credential_ref:form.credentialRef===''?null:form.credentialRef.toLowerCase(),requested_enabled:form.intent===''?null:form.intent==='YES',note:form.note}}
const unsaved=computed(()=>mode.value!==null&&state.value.attempt?.state!=='accepted'&&(state.value.attempt?.state==='rejected'||JSON.stringify(payload())!==initial.value||assetQuery.value!==''||checkedAssets.value.length>0))
const newerVersion=computed(()=>baseline.value&&state.value.selected?.id===baseline.value.id&&state.value.selected.version>baseline.value.version)
const currentStep=computed(()=>state.value.attempt?.state==='accepted'?3:mode.value&&targets.value.length?2:1)
function clearAssets(){assetAbort?.abort();assetAbort=null;++assetEpoch;assetBusy.value=false;assets.value=null;checkedAssets.value=[];assetError.value=null;assetQuery.value='';assetApplied.value=''}
function clearEditor(){mode.value=null;baseline.value=null;initial.value='';validation.value='';targets.value=[];targetPage.value=0;expandedVersion.value=null;Object.assign(form,{name:'',dailyLocalTime:'02:00',credentialRef:'',intent:'',note:null});clearAssets()}
watch(contextKey,()=>{workspace.reset(disposed?null:context());clearEditor();lookupId.value='';if(permitted.value&&!disposed)void workspace.list()},{immediate:true,flush:'sync'})
watch(assetQuery,()=>{assetAbort?.abort();assetAbort=null;++assetEpoch;assetBusy.value=false;assets.value=null;checkedAssets.value=[];assetError.value=null},{flush:'sync'})
async function discard(){if(!unsaved.value)return true;try{await ElMessageBox.confirm('将替换尚未成功保存的计划输入和候选选择；不会自动合并到新版本。是否继续？','保留未保存输入',{confirmButtonText:'确认替换',cancelButtonText:'保留输入',type:'warning'});return true}catch{return false}}
function canPrepare(){if(disposed||!writable.value||state.value.busy||assetBusy.value)return false;if(workspace.unresolved()){ElMessage.warning('原请求结果未知，请按原请求重试，不能替换命令');return false}return true}
async function prepareCreate(){if(!canPrepare())return false;const turn=contextKey.value;if(!await discard()||disposed||turn!==contextKey.value||!writable.value||!workspace.begin())return false;clearEditor();mode.value='CREATE';initial.value=JSON.stringify(payload());return true}
async function prepareFrom(row:BackupPlanDetail){if(!canPrepare()||row.archived)return false;const turn=contextKey.value,target=structuredClone(row);if(!await discard()||disposed||turn!==contextKey.value||!writable.value||!workspace.begin())return false;clearEditor();baseline.value=target;mode.value='UPDATE';targets.value=target.target_asset_ids.map(id=>({id,name:null}));Object.assign(form,{name:target.name,dailyLocalTime:target.daily_local_time,credentialRef:target.credential_ref??'',intent:target.requested_enabled?'YES':'NO',note:target.note});initial.value=JSON.stringify(payload());return true}
async function loadAssets(next=false){
 if(disposed||!mode.value||!canChooseAssets.value||locked.value)return false
 const query=assetQuery.value,cursor=next&&assets.value?.has_more&&assetApplied.value===query?assets.value.next_cursor:null;if(next&&!cursor)return false
 assets.value=null;checkedAssets.value=[];assetError.value=null
 if(query.length>100||!validInspectionText(query,100,false,false,false)){assetError.value=new ApiError(0,'INVALID_BACKUP_ASSET_QUERY','资产查询不能超过100字符或含控制字符','—');return false}
 const scope=context();if(!scope)return false;const turn=++assetEpoch,key=contextKey.value,controller=new AbortController();assetAbort=controller;assetBusy.value=true
 try{const params=new URLSearchParams({page_size:'15',q:query});if(cursor)params.set('cursor',cursor);const raw=await api.request('/assets?'+params,{signal:controller.signal});if(disposed||turn!==assetEpoch||key!==contextKey.value||controller.signal.aborted)return false;try{assets.value=worksheetAssetChoices(raw,scope)}catch{throw new ApiError(0,'INVALID_BACKUP_ASSET_CHOICES','候选设备范围或分页未通过核对，未加入目标','—')}assetApplied.value=query;return true}catch(error){if(!disposed&&turn===assetEpoch&&key===contextKey.value)assetError.value=error;return false}finally{if(!disposed&&turn===assetEpoch&&key===contextKey.value){assetBusy.value=false;assetAbort=null}}
}
function toggleAsset(id:string,checked:boolean){if(locked.value||!mode.value||!canChooseAssets.value||!assets.value?.items.some(a=>a.id===id))return false;checkedAssets.value=checked?(checkedAssets.value.includes(id)?checkedAssets.value:[...checkedAssets.value,id]):checkedAssets.value.filter(value=>value!==id);return true}
function addChecked(){if(locked.value||!mode.value||!canChooseAssets.value||!assets.value||checkedAssets.value.length===0)return false;const ids=[...new Set(checkedAssets.value)];if(ids.some(id=>!assets.value!.items.some(a=>a.id===id)))return false;const existing=new Set(targets.value.map(t=>t.id)),added=ids.filter(id=>!existing.has(id)).map(id=>assets.value!.items.find(a=>a.id===id)!);if(targets.value.length+added.length>1000){validation.value='目标超过1000项技术保护，未截断添加';return false}if(!added.length){validation.value='这些设备已经在明确目标中，不会重复加入';return false}targets.value.push(...added.map(a=>({id:a.id,name:a.name})));checkedAssets.value=[];validation.value='';targetPage.value=Math.floor((targets.value.length-1)/10);return true}
function removeTarget(index:number){if(locked.value||!Number.isInteger(index)||index<0||index>=targets.value.length)return false;targets.value.splice(index,1);targetPage.value=Math.min(targetPage.value,Math.max(0,Math.ceil(targets.value.length/10)-1));return true}
function moveTarget(index:number,offset:-1|1){if(locked.value||!Number.isInteger(index)||index<0||index>=targets.value.length||index+offset<0||index+offset>=targets.value.length)return false;const target=targets.value.splice(index,1)[0]!;targets.value.splice(index+offset,0,target);targetPage.value=Math.floor((index+offset)/10);return true}
function setNoteKnown(known:boolean){if(locked.value)return;form.note=known?form.note??'':null}
async function browse(next=false){validation.value='';expandedVersion.value=null;return workspace.list(next)}
async function select(id:string){validation.value='';expandedVersion.value=null;return workspace.select(id)}
async function history(id:string,next=false){validation.value='';expandedVersion.value=null;return workspace.history(id,next)}
async function lookup(){const id=lookupId.value.toLowerCase();if(!backupPlanUuid(id)){validation.value='请填写完整计划UUID；不会自动选择第一条';return false}return select(id)}
async function save(){if(disposed||locked.value||!mode.value)return false;validation.value='';const turn=contextKey.value;const success=await workspace.submit(mode.value,payload(),baseline.value);if(disposed||turn!==contextKey.value)return false;if(success)ElMessage.success('原请求收据已确认，草稿仍未启用');else if(!state.value.attempt)validation.value='请填写名称、明确目标、HH:mm时间和启用意向；凭据仅可填UUID引用，不能填密码或密钥。未发送新请求';return success}
async function retry(){const turn=contextKey.value;const success=await workspace.retry();if(success&&!disposed&&turn===contextKey.value)ElMessage.success('已恢复原请求收据，没有重复创建或修订');return success}
async function lifecycle(row:BackupPlanDetail,action:'ARCHIVE'|'RESTORE'){
 if(!canPrepare()||row.archived!==(action==='RESTORE'))return false;const turn=contextKey.value,target=structuredClone(row);if(!await discard()||disposed||turn!==contextKey.value)return false
 try{await ElMessageBox.confirm((action==='ARCHIVE'?'归档':'原样恢复')+'“'+target.name+'”并保留全部历史；不会启用计划或执行设备备份。是否继续？',action==='ARCHIVE'?'确认归档草稿':'确认原样恢复草稿',{confirmButtonText:action==='ARCHIVE'?'归档并保留历史':'原样恢复且不启用',cancelButtonText:'取消',type:'warning'})}catch{return false}
 if(disposed||turn!==contextKey.value||!writable.value||!workspace.begin())return false;clearEditor();const success=await workspace.submit(action,{expected_version:target.version},target);if(success&&!disposed&&turn===contextKey.value)ElMessage.success(action==='ARCHIVE'?'已归档并保留历史':'已原样恢复，仍未启用');return success
}
function unlockRejected(){if(state.value.attempt?.state!=='rejected'||!workspace.begin())return false;validation.value='已保留输入并解锁。版本未自动更新；冲突时先回读，再明确按当前版本重新准备';return true}
async function closeEditor(){if(workspace.unresolved()){ElMessage.warning('结果未知，不能关闭并丢失原请求');return false}const turn=contextKey.value;if(!await discard()||disposed||turn!==contextKey.value||state.value.busy)return false;if(state.value.attempt?.state==='rejected'&&!workspace.begin())return false;clearEditor();return true}
async function mayLeave(){if(workspace.unresolved()){ElMessage.warning('先确认原请求结果；普通刷新不能替代原请求重试');return false}const turn=contextKey.value;return await discard()&&!disposed&&turn===contextKey.value}
onBeforeRouteLeave(mayLeave);const unregister=contextTransitionGuards.register(mayLeave)
function beforeUnload(event:BeforeUnloadEvent){if(workspace.unresolved()||unsaved.value){event.preventDefault();event.returnValue=''}}
window.addEventListener('beforeunload',beforeUnload)
onUnmounted(()=>{disposed=true;unregister();workspace.dispose();clearEditor();window.removeEventListener('beforeunload',beforeUnload)})
defineExpose({prepareCreate,prepareFrom,loadAssets,addChecked,removeTarget,moveTarget,setNoteKnown,browse,select,history,save,retry,lifecycle,unlockRejected,closeEditor,payload,form,targets,assetQuery,checkedAssets,assets,state,hasUnresolved:workspace.unresolved})
useWorkspaceReveal(() => state.value.selected?.id, '.current-plan')
useWorkspaceReveal(() => mode.value, '.plan-editor')
</script>
<template>
 <section class="backup-plan-page">
  <div class="page-heading"><div><h1>每日备份计划草稿</h1><p>保存明确设备与时间提案，保留修订历史。这里不会启动设备备份</p></div><button v-if="writable" type="button" :disabled="Boolean(state.busy)||assetBusy||workspace.unresolved()" @click="prepareCreate">准备新计划草稿</button></div>
  <details class="page-guidance"><summary>使用范围与说明</summary><el-alert type="warning" :closable="false" show-icon title="所有草稿未启用、未批准；凭据引用未核验，不执行SSH或自动恢复。真实设备授权、存储和调度仍待完成" /></details>
  <p v-if="!permitted" class="panel">当前无权读取备份计划草稿，或租户正在切换；未展示旧数据</p>
  <template v-else>
   <ol v-if="mode" class="plan-steps" aria-label="备份计划草稿步骤"><li :aria-current="currentStep===1?'step':undefined"><strong>① 明确目标</strong><span>手动勾选当前租户设备</span></li><li :aria-current="currentStep===2?'step':undefined"><strong>② 填写提案</strong><span>时间与意向，不代表启用</span></li><li :aria-current="currentStep===3?'step':undefined"><strong>③ 确认原收据</strong><span>结果未知只重试原请求</span></li></ol>
   <ApiErrorNotice :error="state.error" />
   <section v-if="state.attempt" class="panel original-request" aria-live="polite"><h2>原请求 · {{actions[state.attempt.action]}}</h2><p v-if="state.attempt.state==='uncertain'">结果未知：可能已经提交。输入与原key/body已锁定，刷新列表或当前记录不会确认原写入</p><p v-else-if="state.attempt.state==='accepted'">已确认原请求收据；这不是当前最新状态，也不表示计划已启用</p><p v-else>本次请求已明确拒绝。原输入保留，版本不自动合并</p><div class="actions"><button v-if="state.attempt.state==='uncertain'" type="button" :disabled="Boolean(state.busy)||!writable" @click="retry">使用完全相同原请求重试</button><button v-if="state.attempt.state==='rejected'&&writable" type="button" :disabled="Boolean(state.busy)" @click="unlockRejected">保留输入并解锁修正</button><button v-if="state.attempt.baseline" type="button" :disabled="Boolean(state.busy)" @click="select(state.attempt.baseline.id)">只读回查原记录</button></div></section>
   <form v-form-feedback v-if="mode" class="panel plan-editor" @submit.prevent="save"><h2>{{mode==='CREATE'?'新计划草稿':'按明确版本编辑'}}<span v-if="baseline"> · v{{baseline.version}} · {{baseline.id}}</span></h2><p v-if="newerVersion" class="validation">已回读到更新版本；此处仍保留原版本输入，不会自动合并。请明确按当前版本重新准备</p>
    <fieldset :disabled="locked"><div class="editor-grid"><label>计划名称<input v-model="form.name" aria-label="备份计划名称" maxlength="200" /></label><label>每日时间（Asia/Shanghai）<input v-model="form.dailyLocalTime" aria-label="备份计划每日时间" type="time" step="60" /><span class="hint">02:00为合同默认建议，可修改；不会建立调度任务</span></label><label>启用意向<select v-model="form.intent" aria-label="备份计划启用意向"><option value="">请明确选择</option><option value="NO">暂不申请启用</option><option value="YES">后续申请启用（仍未启用）</option></select></label><label>可选凭据引用UUID<input v-model="form.credentialRef" aria-label="备份计划凭据引用" maxlength="36" placeholder="留空为null；禁止填密码、密钥或连接串" /><span class="hint">仅保存未核验引用，不配置或使用凭据</span></label><div class="full-width"><label class="check-label"><input type="checkbox" :checked="form.note===null" @change="setNoteKnown(!($event.target as HTMLInputElement).checked)" />备注未填写（null）</label><label>备注<textarea v-model="form.note" aria-label="备份计划备注" :disabled="form.note===null" maxlength="8000" placeholder="取消未填写后，可明确保留空备注或原文" /></label></div></div></fieldset>
    <section class="asset-picker"><h3>① 明确选择当前租户设备</h3><p>不会自动选择第一项；已有目标不重复添加。候选名称仅供选择，不表示设备在线或SSH已授权</p><p v-if="!canChooseAssets" class="validation">缺少资产读取能力，不能新增候选；已有目标引用不会自动替换</p><fieldset :disabled="locked||!canChooseAssets"><div class="actions asset-search"><label>资产名称搜索<input v-model="assetQuery" aria-label="备份目标设备搜索" maxlength="100" @keydown.enter.prevent="loadAssets(false)" /></label><button type="button" @click="loadAssets(false)">查询目标设备</button><button type="button" :disabled="!assets?.has_more||assetQuery!==assetApplied" @click="loadAssets(true)">更多候选设备</button></div></fieldset><ApiErrorNotice :error="assetError" /><p v-if="assetBusy" aria-live="polite">正在读取候选，数量未知</p><fieldset v-if="assets" :disabled="locked||!canChooseAssets"><ul class="asset-candidates"><li v-for="a in assets.items" :key="a.id"><label class="check-label"><input type="checkbox" :checked="checkedAssets.includes(a.id)" :aria-label="'选择目标 '+a.id" @change="toggleAsset(a.id,($event.target as HTMLInputElement).checked)" /><span><strong>{{a.name}}</strong><small>{{a.id}}</small></span></label></li></ul><p v-if="!assets.items.length">当前查询没有已登记候选，不代表设备健康或可备份</p><button type="button" :disabled="!checkedAssets.length" @click="addChecked">加入勾选设备</button></fieldset></section>
    <section class="selected-targets"><h3>已明确目标 · {{targets.length}} / 1000（技术保护上限）</h3><p v-if="!targets.length">还未选择目标，不能保存</p><ol :start="targetPage*10+1"><li v-for="(t,i) in targetRows" :key="t.id"><div><strong>{{t.name??'已保存引用，名称未载入'}}</strong><small>{{t.id}}</small></div><div class="actions"><button type="button" :disabled="locked||targetPage*10+i===0" @click="moveTarget(targetPage*10+i,-1)">上移目标</button><button type="button" :disabled="locked||targetPage*10+i+1>=targets.length" @click="moveTarget(targetPage*10+i,1)">下移目标</button><button type="button" :disabled="locked" @click="removeTarget(targetPage*10+i)">移除目标</button></div></li></ol><div v-if="targets.length>10" class="actions"><button type="button" :disabled="targetPage===0" @click="targetPage--">前10个目标</button><span>第{{targetPage+1}} / {{Math.ceil(targets.length/10)}}组</span><button type="button" :disabled="(targetPage+1)*10>=targets.length" @click="targetPage++">后10个目标</button></div></section>
    <p v-if="validation" class="validation" role="alert">{{validation}}</p><div class="actions editor-footer"><button class="primary-button" type="submit" :disabled="locked">{{mode==='CREATE'?'保存新计划草稿':'保存新草稿修订'}}</button><button type="button" :disabled="Boolean(state.busy)" @click="closeEditor">关闭输入</button></div>
   </form>
   <section v-if="state.receipt" class="panel receipt-panel"><h2>原请求确认收据 · v{{state.receipt.version}}</h2><p>{{state.receipt.name}} · {{state.receipt.archived?'已归档':'未启用草稿'}} · 不是当前最新状态</p><details><summary>查看原收据提案</summary><BackupPlanFacts :value="state.receipt" /></details></section>
   <section class="panel"><div class="actions"><h2>已保存草稿（含归档）</h2><button type="button" :disabled="Boolean(state.busy)" @click="browse(false)">只读刷新第一页</button></div><details class="actions lookup"><summary>按标识查询</summary><label>明确计划UUID<input v-model="lookupId" aria-label="备份计划查询ID" maxlength="36" @keydown.enter.prevent="lookup" /></label><button type="button" :disabled="Boolean(state.busy)" @click="lookup">按ID读取当前记录</button></details><p v-if="validation&&!mode" role="alert" class="validation">{{validation}}</p><p v-if="!state.page" class="empty-panel">{{state.busy==='read'?'正在读取，数量未知':state.error?'读取未通过，未显示旧列表':'尚未读取，数量未知'}}</p><template v-else><div class="record-table plan-records" role="region" tabindex="0" aria-label="记录列表，可横向滚动"><table><thead><tr><th>计划名称</th><th>状态</th><th>每日时间</th><th>目标数</th><th>更新时间</th><th>操作</th></tr></thead><tbody><tr v-for="r in state.page.items" :key="r.id" ><td><strong>{{r.name}}</strong><span class="row-secondary">v{{r.version}}</span></td><td>{{r.archived?'已归档':'未启用草稿'}}</td><td>{{r.daily_local_time}}<span class="row-secondary">北京时间</span></td><td>{{r.target_count}}</td><td>{{displayTime(r.recorded_at)}}<span class="row-secondary">凭据{{r.credential_ref===null?'未提供引用':'仅引用未核验'}}</span></td><td><button type="button" :disabled="Boolean(state.busy)" @click="select(r.id)">查看当前提案</button></td></tr></tbody></table></div><p v-if="!state.page.items.length">本页没有已保存草稿，不代表已完成设备备份</p><div class="actions"><span>本页{{state.page.items.length}}条 · {{state.paged?'续页':'第一页'}}，不是设备总体数量</span><button type="button" :disabled="Boolean(state.busy)||!state.page.has_more" @click="browse(true)">下一页草稿</button></div></template></section>
   <section v-if="state.selected" class="panel current-plan"><h2>当前回读：{{state.selected.name}}</h2><p>{{state.selected.id}} · {{state.selected.archived?'已归档':'未启用草稿'}} · v{{state.selected.version}}</p><div class="actions"><button v-if="writable&&!state.selected.archived" type="button" :disabled="Boolean(state.busy)||assetBusy||workspace.unresolved()" @click="prepareFrom(state.selected)">按当前版本编辑</button><button v-if="writable" type="button" :disabled="Boolean(state.busy)||assetBusy||workspace.unresolved()" @click="lifecycle(state.selected,state.selected.archived?'RESTORE':'ARCHIVE')">{{state.selected.archived?'原样恢复且不启用':'归档并保留历史'}}</button><button type="button" :disabled="Boolean(state.busy)" @click="history(state.selected.id)">读取草稿历史</button></div><BackupPlanFacts :value="state.selected" /></section>
   <section v-if="state.history" class="panel plan-history"><h2>不可变修订历史</h2><article v-for="r in state.history.items" :key="r.version"><div class="actions"><h3>v{{r.version}} · {{actions[r.action]}} · {{r.name}}</h3><button type="button" :aria-expanded="expandedVersion===r.version" @click="expandedVersion=expandedVersion===r.version?null:r.version">{{expandedVersion===r.version?'收起该版提案':'展开该版提案'}}</button></div><p>{{displayTime(r.recorded_at)}} · {{r.target_count}}个目标 · 未启用</p><BackupPlanFacts v-if="expandedVersion===r.version" :value="r" /></article><div class="actions"><button type="button" :disabled="Boolean(state.busy)" @click="history(state.history.plan_id)">读取最新历史</button><button type="button" :disabled="Boolean(state.busy)||!state.history.has_more" @click="history(state.history.plan_id,true)">更早草稿历史</button></div></section>
  </template>
 </section>
</template>
